  `actual_collected_time` datetime NULL DEFAULT NULL COMMENT '实际揽收时间',
  `actual_commit_time` datetime NULL DEFAULT NULL COMMENT '实际提交时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
