  `cur_task_id` bigint NULL DEFAULT 0 COMMENT '来源快递任务id',
  `task_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务类型:1  揽收 2 运输 3 中转 4派送 ',
  `charge_emp_id` bigint NOT NULL DEFAULT 0 COMMENT '负责人id',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_rollback` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否回退中',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `is_deleted` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记（0:不可用 1:可用）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 62254 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流单追踪信息' ROW_FORMAT = COMPACT;

