-- ----------------------------
-- Table structure for transport_task
-- ----------------------------
DROP TABLE IF EXISTS `transport_task`;
CREATE TABLE `transport_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `shift_id` bigint NULL DEFAULT NULL COMMENT '车次id',
  `line_id` bigint NULL DEFAULT NULL COMMENT '路线id',
  `start_org_id` bigint NOT NULL DEFAULT 0 COMMENT '起始机构id',
  `start_org_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '起始机构名称',
  `end_org_id` bigint NOT NULL DEFAULT 0 COMMENT '目的机构id',
  `end_org_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目的机构名称',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '任务状态',
  `order_num` int NULL DEFAULT NULL COMMENT '运单个数',
  `driver1_emp_id` bigint NULL DEFAULT NULL COMMENT '司机1id',
  `driver1_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '司机1名称',
  `driver2_emp_id` bigint NULL DEFAULT NULL COMMENT '司机2id',
  `driver2_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '司机2名称',
  `truck_id` bigint NULL DEFAULT NULL COMMENT '卡车id',
  `truck_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '卡车号牌',
  `actual_start_time` datetime NULL DEFAULT NULL COMMENT '实际启动时间',
  `actual_end_time` datetime NULL DEFAULT NULL COMMENT '实际到达时间',
  `actual_distance` decimal(16, 2) NULL DEFAULT NULL COMMENT '实际行驶距离',
  `create_time` timestamp NOT NULL COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `is_deleted` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记（0:不可用 1:可用）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 102106 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运输任务表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of transport_task
-- ----------------------------

-- ----------------------------
-- Table structure for transport_task_detail
-- ----------------------------
DROP TABLE IF EXISTS `transport_task_detail`;
CREATE TABLE `transport_task_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `transport_task_id` bigint NOT NULL DEFAULT 0 COMMENT '运输任务id',
  `order_id` bigint NOT NULL DEFAULT 0 COMMENT '运单id',
  `sorter_emp_id` bigint NULL DEFAULT NULL COMMENT '分拣员id',
  `create_time` timestamp NOT NULL COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `is_deleted` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标记（0:不可用 1:可用）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_task_id`(`transport_task_id` ASC) USING BTREE,
  INDEX `idx_sorter_emp`(`sorter_emp_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9755 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运单与运输任务关联表' ROW_FORMAT = COMPACT;

