-- ----------------------------
-- Table structure for truck_driver
-- ----------------------------
DROP TABLE IF EXISTS `truck_driver`;
CREATE TABLE `truck_driver`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `emp_id` bigint NULL DEFAULT NULL COMMENT '雇员编号',
  `org_id` bigint NULL DEFAULT NULL COMMENT '机构号',
  `team_id` bigint NULL DEFAULT NULL COMMENT '车队号',
  `license_type` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准驾车型',
  `init_license_date` date NULL DEFAULT NULL COMMENT '初次领证日期',
  `expire_date` date NULL DEFAULT NULL COMMENT '有效截止日期',
  `license_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驾驶证号',
  `license_picture_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驾照图片',
  `is_enabled` int NULL DEFAULT NULL COMMENT '状态 0：禁用 1：正常',
  `create_time` timestamp NOT NULL COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `is_deleted` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记（0:不可用 1:可用）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1099 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '司机驾驶证表' ROW_FORMAT = Dynamic;

